-- 705: Save as Dataset compiles the path to a job spec, and the build runs it.
--
--   "You can save the results of your path as a new, separate dataset in Foundry. The sequence of transformations you performed in the path is saved as a Foundry *job*, and is executed as part of the Foundry build system."
--   — contour/core-concepts.md
--
-- Foundry's own word for the artifact is on a page the reading first missed:
--
--   "Contour paths can be \"saved as\" datasets. This saves the underlying code generated by the Contour backend into a dataset job specification. This dataset build can then be run on a schedule or ad hoc."
--   — contour/compute-usage.md
--
-- So save_contour_path_as_dataset PUBLISHES A job_specs ROW (the 692 upsert
-- shape) whose SQL this compiler generates from the boards. Where Foundry's
-- backend generates Spark, ours generates the job spec's Postgres SQL — the
-- Spark divergence for Contour, scoped to this one function.
--
-- THE RULES THE COMPILER HOLDS, each from its page:
--
--   "All datasets built in Contour will always use the latest versions of the input datasets."
--   — contour/datasets-save.md
--
-- (the job runner already reads master views, so the path's pinned
-- transaction is ignored here by construction);
--
--   "You will not be able to save a path with a Restricted View as an input as a dataset."
--   — contour/datasets-save.md
--
-- (refused, transitively through path heads);
--
--   "You must use the `Update` button to pick up logic changes."
--   — contour/datasets-save.md
--
-- (the job spec changes only when this function runs again — 493's guard
-- bumps its version on every logic change);
--
--   Use parameters in filters and expressions to quickly manipulate data by typing "$". Filtering will be ignored when no value is set for a parameter.
--   — contour/images/overview.png
--
-- (a filter naming a parameter with no default COMPILES TO NOTHING — the
-- capture's rule, which is looser than evaluating false and being stricter
-- than Foundry is the recorded trap);
--
--   "Some boards that allow you to calculate aggregate metrics have an option to pivot. This switches your working dataset to the aggregate data computed in that board, instead of the original dataset. Any boards that follow will use the new aggregate dataset."
--   — contour/analysis-switch-aggregated.md
--
-- (a pivoted histogram turns the working set into its buckets and counts).
--
-- A disabled board compiles to nothing — visible but unapplied. Display-only
-- boards (summary, table, an unpivoted histogram) compile to nothing except
-- their SELECTION, which is a filter the board applies downstream.

CREATE FUNCTION public.compile_contour_path(p_path uuid)
RETURNS text LANGUAGE plpgsql STABLE
SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  p record; b record; sql_text text; cond text; col text; op text;
  val jsonb; param record; agg boolean := false;
BEGIN
  SELECT * INTO p FROM public.contour_paths WHERE id = p_path;
  IF p.id IS NULL THEN
    RAISE EXCEPTION 'Contour:NoSuchPath — % is not a path you can see', p_path;
  END IF;
  IF p.head_restricted_view_id IS NOT NULL THEN
    RAISE EXCEPTION 'Contour:RestrictedViewInput — you will not be able to save a path with a Restricted View as an input as a dataset';
  END IF;
  IF p.head_dataset_id IS NOT NULL THEN
    -- the job runner exposes each declared input as a CTE named by api_name,
    -- and that CTE carries the physical table's _row and _file columns — the
    -- schema's own columns are selected explicitly so they never reach the
    -- output
    SELECT format('SELECT %s FROM %I',
                  (SELECT string_agg(format('%I', f ->> 'name'), ', ')
                     FROM (SELECT sc.fields FROM public.dataset_schemas sc
                            WHERE sc.dataset_id = d.id
                            ORDER BY sc.created_at DESC LIMIT 1) latest,
                          jsonb_array_elements(latest.fields) f),
                  d.api_name)
      INTO sql_text
      FROM public.datasets d WHERE d.id = p.head_dataset_id;
    IF sql_text IS NULL OR sql_text LIKE 'SELECT  FROM%' THEN
      RAISE EXCEPTION 'Contour:HeadHasNoSchema — the head dataset has no schema to analyze';
    END IF;
  ELSE
    -- a path-headed path inlines its upstream, recursively — the analysis
    -- is self-contained, so the whole chain lands in one job
    sql_text := format('SELECT * FROM (%s) AS upstream', public.compile_contour_path(p.head_path_id));
  END IF;

  FOR b IN SELECT * FROM public.contour_boards cb
            WHERE cb.path_id = p_path ORDER BY cb.position, cb.created_at LOOP
    CONTINUE WHEN NOT b.enabled;

    IF b.kind = 'filter' THEN
      col := b.configuration ->> 'column';
      op  := coalesce(b.configuration ->> 'op', '=');
      IF op NOT IN ('=', '<>', '>', '>=', '<', '<=') THEN
        RAISE EXCEPTION 'Contour:UnknownFilterOp — % is not an operator the filter board compiles', op;
      END IF;
      IF b.configuration ? 'parameter' THEN
        SELECT * INTO param FROM public.contour_parameters cp
         WHERE cp.analysis_id = p.analysis_id
           AND cp.name = b.configuration ->> 'parameter';
        IF param.id IS NULL THEN
          RAISE EXCEPTION 'Contour:NoSuchParameter — $%s is not a parameter of this analysis', b.configuration ->> 'parameter';
        END IF;
        -- Filtering is ignored when no value is set for a parameter — the
        -- capture rule quoted in this file's header
        CONTINUE WHEN param.default_value IS NULL;
        val := param.default_value;
      ELSE
        val := b.configuration -> 'value';
      END IF;
      cond := format('%I %s %L', col, op,
                     CASE jsonb_typeof(val) WHEN 'string' THEN val #>> '{}' ELSE val::text END);
      IF coalesce(b.configuration ->> 'mode', 'keep') = 'remove' THEN
        cond := format('NOT (%s)', cond);
      END IF;
      sql_text := format('SELECT * FROM (%s) AS s WHERE %s', sql_text, cond);

    ELSIF b.kind = 'expression' THEN
      -- passthrough: the dialect is Postgres, the recorded divergence. A
      -- derived column or a filter, the board's two documented jobs.
      IF b.configuration ? 'new_column' THEN
        sql_text := format('SELECT s.*, (%s) AS %I FROM (%s) AS s',
                           b.configuration ->> 'expression',
                           b.configuration ->> 'new_column', sql_text);
      ELSE
        sql_text := format('SELECT * FROM (%s) AS s WHERE (%s)',
                           sql_text, b.configuration ->> 'expression');
      END IF;

    ELSIF b.kind = 'histogram' THEN
      col := b.configuration ->> 'bucket_column';
      -- a selection is the board filtering downstream: kept or removed bars
      IF b.selection IS NOT NULL AND jsonb_array_length(coalesce(b.selection -> 'values', '[]'::jsonb)) > 0 THEN
        cond := format('%I IN (SELECT value #>> ''{}'' FROM jsonb_array_elements(%L::jsonb))',
                       col, (b.selection -> 'values')::text);
        IF coalesce(b.selection ->> 'mode', 'keep') = 'remove' THEN
          cond := format('NOT (%s)', cond);
        END IF;
        sql_text := format('SELECT * FROM (%s) AS s WHERE %s', sql_text, cond);
      END IF;
      -- pivot: the working set BECOMES the aggregate
      IF b.pivoted THEN
        sql_text := format('SELECT %I, count(*) AS count FROM (%s) AS s GROUP BY %I',
                           col, sql_text, col);
        agg := true;
      END IF;

    ELSIF b.kind IN ('summary', 'table') THEN
      CONTINUE; -- display only

    ELSE
      RAISE EXCEPTION 'Contour:BoardNotCompiled — % has no compilation here', b.kind;
    END IF;
  END LOOP;

  RETURN sql_text;
END $$;
COMMENT ON FUNCTION public.compile_contour_path(uuid) IS
  'The Contour backend''s code generation, in the substrate we run: boards become one nested SELECT over the head input''s CTE (the job runner names each declared input by its api_name, 493). Filters compile their predicate — or NOTHING when their parameter has no value, the capture''s rule; expressions pass through as Postgres, the recorded divergence; a pivoted histogram groups the working set into its buckets; disabled and display-only boards compile to nothing but their selection. Refuses a restricted-view head, transitively.';

-- ── the save, which publishes ───────────────────────────────────────────────

CREATE FUNCTION public.save_contour_path_as_dataset(p_path uuid, p_output uuid)
RETURNS uuid LANGUAGE plpgsql
SET search_path TO 'public', 'pg_temp' AS $$
DECLARE
  p record; logic text; walk uuid; seen integer := 0;
BEGIN
  SELECT * INTO p FROM public.contour_paths WHERE id = p_path;
  IF p.id IS NULL THEN
    RAISE EXCEPTION 'Contour:NoSuchPath — % is not a path you can see', p_path;
  END IF;
  logic := public.compile_contour_path(p_path);

  -- the output's master branch exists before the first build writes to it,
  -- the same provisioning sync_table_region does
  IF NOT EXISTS (SELECT 1 FROM public.dataset_branches b
                  WHERE b.dataset_id = p_output AND b.name = 'master') THEN
    INSERT INTO public.dataset_branches (dataset_id, name) VALUES (p_output, 'master');
  END IF;

  -- the declared inputs: every dataset the chain and its boards read.
  -- "In a project scoped analysis, all inputs and outputs must be in scope"
  -- is project scoping, which this platform records but does not enforce —
  -- scoped analyses are not built.
  DELETE FROM public.dataset_inputs WHERE dataset_id = p_output;
  walk := p_path;
  WHILE walk IS NOT NULL AND seen < 64 LOOP
    seen := seen + 1;
    INSERT INTO public.dataset_inputs (dataset_id, input_dataset_id)
    SELECT p_output, x.head_dataset_id FROM public.contour_paths x
     WHERE x.id = walk AND x.head_dataset_id IS NOT NULL
    ON CONFLICT DO NOTHING;
    INSERT INTO public.dataset_inputs (dataset_id, input_dataset_id)
    SELECT DISTINCT p_output, cb.input_dataset_id FROM public.contour_boards cb
     WHERE cb.path_id = walk AND cb.input_dataset_id IS NOT NULL
    ON CONFLICT DO NOTHING;
    SELECT x.head_path_id INTO walk FROM public.contour_paths x WHERE x.id = walk;
  END LOOP;

  -- the 692 shape: one spec per output dataset, publishing again REPLACES
  -- the logic — which is the Update button, and 493's guard bumps the version
  INSERT INTO public.job_specs (output_dataset_id, logic_sql, published_by)
  VALUES (p_output, logic, auth.uid())
  ON CONFLICT (output_dataset_id) DO UPDATE
    SET logic_sql = EXCLUDED.logic_sql,
        published_by = EXCLUDED.published_by,
        published_at = now();
  RETURN p_output;
END $$;
COMMENT ON FUNCTION public.save_contour_path_as_dataset(uuid, uuid) IS
  'The Save as Dataset button, and the Update button when called again: compiles the path and publishes "the underlying code generated by the Contour backend into a dataset job specification" (contour/compute-usage). The job always reads latest inputs — "All datasets built in Contour will always use the latest versions of the input datasets" (contour/datasets-save) — because the job runner reads master views; the path''s pin never reaches the job. Logic changes land only when this runs again: "You must use the Update button to pick up logic changes." INVOKER.';

-- ── PROVED BY DOING: the whole loop, through run_build ──────────────────────

DO $$
DECLARE
  org uuid; sp uuid; proj uuid; a uuid; p1 uuid; p2 uuid;
  ds uuid; outd uuid; outd2 uuid; br uuid; txn uuid; fid uuid; phys text;
  rv uuid; prv uuid; bld uuid; n integer; got text;
  u1 uuid := gen_random_uuid(); before text;
BEGIN
  before := current_setting('request.jwt.claims', true);
  BEGIN
    INSERT INTO public.organizations (name) VALUES ('ct-705') RETURNING id INTO org;
    INSERT INTO public.spaces (name) VALUES ('ct-705') RETURNING id INTO sp;
    INSERT INTO public.space_organizations (space_id, organization_id) VALUES (sp, org);
    INSERT INTO auth.users (id, instance_id, aud, role, email)
    VALUES (u1, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'ct705@beacon.test');
    INSERT INTO public.users (id, email, role, organization_id)
    VALUES (u1, 'ct705@beacon.test', 'admin', org);
    PERFORM set_config('request.jwt.claims',
      json_build_object('sub', u1::text,
        'app_metadata', json_build_object('role', 'admin', 'org_id', org))::text, true);
    INSERT INTO public.projects (organization_id, space_id, api_name, name)
    VALUES (org, sp, 'ct_705', 'CT 705') RETURNING id INTO proj;
    INSERT INTO public.project_role_grants (project_id, user_id, role, organization_id)
    VALUES (proj, u1, 'owner', org);

    -- the input dataset: four taxi rows
    INSERT INTO public.datasets (organization_id, project_id, api_name, name)
    VALUES (org, proj, 'trips_705', 'trips_705') RETURNING id INTO ds;
    INSERT INTO public.dataset_branches (dataset_id, name) VALUES (ds, 'master') RETURNING id INTO br;
    INSERT INTO public.dataset_transactions (dataset_id, branch_id, txn_type)
    VALUES (ds, br, 'SNAPSHOT') RETURNING id INTO txn;
    INSERT INTO public.dataset_schemas (dataset_id, transaction_id, fields)
    VALUES (ds, txn, '[{"name": "city", "type": "STRING"}, {"name": "fare", "type": "DOUBLE"}]'::jsonb);
    SELECT public.dataset_materialize(ds, txn) INTO phys;
    INSERT INTO public.dataset_files (dataset_id, transaction_id, logical_path, row_count)
    VALUES (ds, txn, 'seed/trips.rows', 4) RETURNING id INTO fid;
    EXECUTE format('INSERT INTO datasets.%I (_file, city, fare) VALUES ($1, ''ATH'', 12), ($1, ''ATH'', 30), ($1, ''SKG'', 8), ($1, ''SKG'', 22)', phys) USING fid;
    PERFORM public.commit_transaction(txn);
    INSERT INTO public.datasets (organization_id, project_id, api_name, name)
    VALUES (org, proj, 'expensive_705', 'expensive_705') RETURNING id INTO outd;
    INSERT INTO public.datasets (organization_id, project_id, api_name, name)
    VALUES (org, proj, 'counts_705', 'counts_705') RETURNING id INTO outd2;

    -- the analysis: filter fare >= 10, expression doubles the fare
    SELECT public.create_contour_analysis(proj, 'Taxi 705') INTO a;
    INSERT INTO public.contour_paths (analysis_id, name, head_dataset_id)
    VALUES (a, 'Main', ds) RETURNING id INTO p1;
    INSERT INTO public.contour_boards (path_id, position, kind, configuration)
    VALUES (p1, 0, 'filter', '{"mode": "keep", "column": "fare", "op": ">=", "value": 10}'::jsonb);
    INSERT INTO public.contour_boards (path_id, position, kind, configuration)
    VALUES (p1, 1, 'expression', '{"expression": "fare * 2", "new_column": "double_fare"}'::jsonb);
    -- a disabled filter that would empty the set — visible, unapplied
    INSERT INTO public.contour_boards (path_id, position, kind, enabled, configuration)
    VALUES (p1, 2, 'filter', false, '{"mode": "keep", "column": "fare", "op": ">", "value": 1000}'::jsonb);
    -- a parameterised filter with NO default — ignored by the capture's rule
    INSERT INTO public.contour_parameters (analysis_id, name, param_type)
    VALUES (a, 'City', 'String');
    INSERT INTO public.contour_boards (path_id, position, kind, configuration)
    VALUES (p1, 3, 'filter', '{"mode": "keep", "column": "city", "op": "=", "parameter": "City"}'::jsonb);

    -- 1. SAVE, BUILD, CHECK THE ROWS: fare>=10 keeps 3 of 4; the disabled
    --    and unset-parameter filters drop out; double_fare is derived.
    PERFORM public.save_contour_path_as_dataset(p1, outd);
    IF NOT EXISTS (SELECT 1 FROM public.job_specs WHERE output_dataset_id = outd) THEN
      RAISE EXCEPTION 'the save published no job specification';
    END IF;
    SELECT public.run_build(ARRAY[outd], true) INTO bld;
    -- builds speak the API vocabulary (SUCCEEDED, not the job token)
    IF (SELECT status FROM public.builds WHERE id = bld) <> 'SUCCEEDED' THEN
      RAISE EXCEPTION 'the build did not complete: %',
        (SELECT string_agg(coalesce(j.state, '?') || ':' || coalesce(j.error, '(no error)'), ' | ')
           FROM public.build_jobs j WHERE j.build_id = bld);
    END IF;
    SELECT d.physical_table INTO phys FROM public.datasets d WHERE d.id = outd;
    EXECUTE format('SELECT count(*) FROM datasets.%I', phys) INTO n;
    IF n <> 3 THEN RAISE EXCEPTION 'the saved dataset holds % rows, not 3', n; END IF;
    EXECUTE format('SELECT count(*) FROM datasets.%I WHERE double_fare = 60', phys) INTO n;
    IF n <> 1 THEN RAISE EXCEPTION 'the 30-fare row should double to 60'; END IF;

    -- 2. THE PARAMETER GAINS A DEFAULT, UPDATE PICKS IT UP — and only Update:
    --    "You must use the Update button to pick up logic changes."
    UPDATE public.contour_parameters SET default_value = '"ATH"'::jsonb
     WHERE analysis_id = a AND name = 'City';
    SELECT js.logic_sql INTO got FROM public.job_specs js WHERE js.output_dataset_id = outd;
    IF got LIKE '%ATH%' THEN
      RAISE EXCEPTION 'the job spec changed without Update';
    END IF;
    PERFORM public.save_contour_path_as_dataset(p1, outd);
    SELECT public.run_build(ARRAY[outd], true) INTO bld;
    EXECUTE format('SELECT count(*) FROM datasets.%I', phys) INTO n;
    IF n <> 2 THEN RAISE EXCEPTION 'with City=ATH the saved dataset holds % rows, not 2', n; END IF;

    -- 3. A PIVOTED HISTOGRAM on a downstream path: the common-input DAG
    --    compiles recursively and the working set becomes buckets.
    INSERT INTO public.contour_paths (analysis_id, name, head_path_id, position)
    VALUES (a, 'Counts', p1, 1) RETURNING id INTO p2;
    INSERT INTO public.contour_boards (path_id, position, kind, pivoted, configuration)
    VALUES (p2, 0, 'histogram', true, '{"bucket_column": "city"}'::jsonb);
    PERFORM public.save_contour_path_as_dataset(p2, outd2);
    SELECT public.run_build(ARRAY[outd2], true) INTO bld;
    SELECT d.physical_table INTO phys FROM public.datasets d WHERE d.id = outd2;
    EXECUTE format('SELECT count(*) FROM datasets.%I', phys) INTO n;
    IF n <> 1 THEN RAISE EXCEPTION 'the pivoted result holds % bucket(s), not 1 (ATH only)', n; END IF;
    EXECUTE format('SELECT count FROM datasets.%I WHERE city = ''ATH''', phys) INTO n;
    IF n <> 2 THEN RAISE EXCEPTION 'ATH should count 2, got %', n; END IF;

    -- 4. A RESTRICTED-VIEW HEAD REFUSES TO SAVE, including through a chain.
    INSERT INTO public.restricted_views (organization_id, project_id, input_dataset_id,
                                         api_name, name, policy)
    VALUES (org, proj, ds, 'rv_705', 'RV 705',
      '{"match": "all", "rules": [{"left": {"user_attribute": "user_id"}, "comparison": "equal", "right": {"column": "city"}}]}'::jsonb)
    RETURNING id INTO rv;
    INSERT INTO public.contour_paths (analysis_id, name, head_restricted_view_id, position)
    VALUES (a, 'Guarded', rv, 2) RETURNING id INTO prv;
    BEGIN
      PERFORM public.save_contour_path_as_dataset(prv, outd2);
      RAISE EXCEPTION 'a restricted-view head was saved as a dataset';
    EXCEPTION WHEN OTHERS THEN
      IF SQLERRM NOT LIKE 'Contour:RestrictedViewInput%' THEN RAISE; END IF;
    END;

    RAISE EXCEPTION 'rollback the probe';
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('request.jwt.claims', coalesce(before, ''), true);
    IF SQLERRM <> 'rollback the probe' THEN RAISE; END IF;
    RAISE NOTICE '705 proved, as the caller, through run_build: the saved path is a job specification whose build writes 3 of 4 rows with the derived column while the disabled filter and the unset parameter compile to nothing; giving the parameter a default changes nothing until Update republishes, then the build narrows to 2; a pivoted histogram on a path-headed path compiles the chain recursively into ATH:2; and a restricted-view head refuses to save';
  END;
END $$;
